<div class="table-scroll"><table><thead><tr><th>OSY ID</th><th>Full name</th><th>Age / Sex</th><?php if (empty($compact)): ?><th>Address</th><?php endif; ?><th>Employment</th><th>Status</th><th class="no-print action-heading">Action</th></tr></thead><tbody>
<?php if (!$rows): ?><tr><td colspan="<?= empty($compact) ? 7 : 6 ?>"><div class="empty-state"><?= icon('records') ?><strong><?= !empty($_GET['q']) || !empty($_GET['sex']) || !empty($_GET['status']) || !empty($_GET['employment_status']) ? 'No matching records' : 'No OSY records yet' ?></strong><p><?= !empty($archived) ? 'Archived records will appear here.' : 'Register a youth to start building your community records, or adjust your filters.' ?></p><a class="text-link no-print" href="<?= e(url('register')) ?>">Register OSY <?= icon('arrow') ?></a></div></td></tr><?php endif; ?>
<?php foreach ($rows as $row): ?><tr><td class="id-cell"><?= e($row['osy_id']) ?></td><td><div class="person-cell"><?= avatar($row) ?><span><?= e($row['full_name']) ?></span></div></td><td><?= age($row['birthdate']) ?><span class="cell-divider">/</span><?= e($row['sex']) ?></td><?php if (empty($compact)): ?><td class="address-cell"><?= e($row['address']) ?></td><?php endif; ?><td><span class="employment-label <?= strtolower(e($row['employment_status'])) ?>"><?= e($row['employment_status']) ?></span></td><td><?= badge($row['status']) ?></td><td class="no-print"><a class="row-action" href="<?= e(url($page === 'idcards' ? 'card' : 'profile', ['id' => $row['id']])) ?>"><?= $page === 'idcards' ? 'Preview ID' : 'View' ?> <?= icon('arrow') ?></a></td></tr><?php endforeach; ?>
</tbody></table></div>
